-- Preserve exact Arabic source excerpts for the current Monshaat-derived tracker actions.
-- This is source traceability only; it does not assert that consultant recommendations are verified facts.

update public.monshaat_tasks
set original_arabic = case task_key
  when 'html-1' then 'ركز على شريحة واحدة كبداية مثل كبار السن القادرين على استخدام الواتس لأنهم أسهل في التبني'
  when 'html-3' then 'نموذج الدفع الثنائي: وجه الخطاب التسويقي للأبناء (المُشتري) لتحقيق الأمان، واجعل التطبيق فائق البساطة للمسن (المستخدم).'
  when 'html-5' then 'اطلع على منهج MIT لريادة الأعمال عشان ترتب نموذج العمل وتشوف ايش النموذج الاكثر ابتكارا وربحية ونموا'
  when 'html-7' then 'طور نسخة MVP أقوى تربط بين الذكاء الاصطناعي والواتس وتضيف تذكير بالأدوية ومتابعة بسيطة بدون مسؤولية طبية'
  when 'html-8' then 'طور نسخة MVP أقوى تربط بين الذكاء الاصطناعي والواتس وتضيف تذكير بالأدوية ومتابعة بسيطة بدون مسؤولية طبية'
  when 'html-9' then 'التنبيهات والتقرير الدوري'
  when 'html-10' then 'التأكد من تصميم واجهات بسيطة وسهلة الاستخدام تناسب كبار السن ورعاتهم، مع أتمتة نظام التنبيهات والتقرير الدوري.'
  when 'html-11' then 'استخدم منصات بناء التطبيقات السريعة لإطلاق نسخة أولى بدون تكلفة عالية'
  when 'html-13' then 'اختبار الحلقات المغلقة: اتجه للجمعيات المتخصصة (مثل وقار) ومراكز الرعاية لتجربة المنتج مع 50 مستخدماً قبل إطلاق التسويق العام.'
  when 'html-14' then 'اختبار الحلقات المغلقة: اتجه للجمعيات المتخصصة (مثل وقار) ومراكز الرعاية لتجربة المنتج مع 50 مستخدماً قبل إطلاق التسويق العام.'
  when 'html-15' then 'نموذج الدفع الثنائي: وجه الخطاب التسويقي للأبناء (المُشتري) لتحقيق الأمان، واجعل التطبيق فائق البساطة للمسن (المستخدم).'
  when 'html-16' then 'تحديد خطة التنفيذ واستراتيجية السوق (GTM & Implementation Plan): الاعتماد على منهجية إطلاق تدريجية تبدأ بالشراكة مع الجمعيات والمتخصصين في رعاية كبار السن لكسب ثقة المستخدمين وتسهيل الوصول للعملاء الهدف.'
  when 'html-17' then 'تحديد خطة التنفيذ واستراتيجية السوق (GTM & Implementation Plan): الاعتماد على منهجية إطلاق تدريجية تبدأ بالشراكة مع الجمعيات والمتخصصين في رعاية كبار السن لكسب ثقة المستخدمين وتسهيل الوصول للعملاء الهدف.'
  when 'html-18' then 'اشتراكات مبكرة: اعتمد نموذج اشتراك شهري للخدمات الأساسية للوصول لنقطة التعادل المالي سريعاً دون حرق السيولة'
  when 'html-19' then 'اشتراكات مبكرة: اعتمد نموذج اشتراك شهري للخدمات الأساسية للوصول لنقطة التعادل المالي سريعاً دون حرق السيولة'
  when 'html-20' then 'الاحتياجات - إستشارات قانونية'
  when 'html-21' then 'ترخيص ريادي من MISA: اختر ترخيص ريادة الأعمال من وزارة الاستثمار لتأسيس شركة بشرط رأس مال مرن ومتطلبات مخفضة للمشاريع الابتكارية.'
  when 'html-22' then 'المركز السعودي للأعمال: أصدر السجل التجاري وعقد التأسيس إلكترونياً وبشكل موحد، مع تحديد الأنشطة التقنية أو الصحية بدقة.'
  when 'html-23' then 'شركة ذات مسؤولية محدودة: أسس الكيان كـ (LLC) لتسهيل دخول المستثمرين وتوزيع الحصص بحوكمة'
  when 'html-24' then 'المركز السعودي للأعمال: أصدر السجل التجاري وعقد التأسيس إلكترونياً وبشكل موحد، مع تحديد الأنشطة التقنية أو الصحية بدقة.'
  when 'html-25' then 'الامتثال التشريعي الصحي: الالتزام بالأنظمة الخاصة بالرعاية الصحية وحماية البيانات الطبية ونقلها وفق اشتراطات الجهات التنظيمية.'
  when 'html-26' then 'الاعتماد على الذكاء الاصطناعي كمرافق لكبير السن يحتاج ضبط قانوني وأخلاقي خصوصاً لو صار فيه تذكير بالأدوية أو متابعة صحية'
  when 'html-27' then 'عدم وضوح الشكل القانوني للمشروع رغم وجود رخصة عمل حر وهذا يحد من التوسع أو التقديم على المسرعات'
  when 'html-29' then 'حفظ المنتج والكود في الملكية الفكرية بعد الانتهاء'
  when 'html-31' then 'بناء وتطوير العرض التقديمي (Pitch Deck Construction): التوجيه بصياغة وإعداد العرض التقديمي لمشروع ElderWise وفق التسلسل الاستثماري القياسي لإبراز نطاق المشروع (Project Scope) والقيمة المضافة لرعاية كبار السن عن بعد.'
  when 'html-32' then 'بناء وتطوير العرض التقديمي (Pitch Deck Construction): التوجيه بصياغة وإعداد العرض التقديمي لمشروع ElderWise وفق التسلسل الاستثماري القياسي لإبراز نطاق المشروع (Project Scope) والقيمة المضافة لرعاية كبار السن عن بعد.'
  when 'html-35' then 'السعي المستمر للاحتضان والعمل تحت مظلة رسمية: التوصية بالتقديم الفوري والبحث عن حاضنات ومسرعات الأعمال التقنية والصحية الوطنية لوضع المشروع في إطار رسمي يوفر الدعم، التسهيلات، والتراخيص المبدئية.'
  when 'html-36' then 'التوصال والحجز مع المرشدة عبير - لمعرفة تفاصيل برامج مسك Launchpad واخذ الخطاب'
  when 'html-37' then 'سجّل المشروع في ImpactHub لو تبغى توسع نشاطك الاجتماعي impacthub.net'
  when 'html-38' then 'المسرعات التقنية: انضم لمسرعات مثل InspireU أو "جادة 30" للحصول على التمويل الأولي والإرشاد وشبكات العلاقات.'
  when 'html-39' then 'حاضنات الأثر الاجتماعي: استهدف حاضنات القطاع غير الربحي والجمعيات الصحية المهتمة باقتصاد كبار السن (Silver Economy).'
  when 'html-40' then 'المستثمرون الملاك: اعرض الـ MVP على شبكات مثل "عقال" للوصول لمستثمرين مهتمين بقطاعات الصحة الذكية والخدمات المساندة'
  when 'html-41' then 'E3 venture متاح للتقديم'
  when 'html-42' then 'تحدي الذكاء الاصطناعي في خدمة المحتوى الإسلامي باذل بالرياض في ٢٩ سبتمبر ٢٠٢٦ بجائزة قدرها ٢٠٠ ألف ريال'
  when 'html-43' then 'جائزة كابسارك للغة العربية عن بعد في ٣٠ سبتمبر ٢٠٢٦'
  when 'html-44' then 'رواد مستقبل المعادن من وزارة الصناعة والثروة المعدنية في الرياض وعن بعد في ٣٠ سبتمبر ٢٠٢٦'
  when 'html-45' then 'معسكر مستقبل ابتكارات الحج من وزارة الحج والعمرة في جدة في ٣٠ سبتمبر ٢٠٢٦'
  when 'html-46' then 'تحدي طويق البرمجي من أكاديمية طويق في الرياض في ٣٠ سبتمبر ٢٠٢٦'
  when 'html-47' then 'هاكاثون الابتكار الصحي الرقمي النسخة الثانية من جامعة الملك سعود في الرياض في ١ أكتوبر ٢٠٢٦ بجائزة مليون ريال'
  when 'html-48' then 'تحدي الكراج في الرياض في ١ أكتوبر ٢٠٢٦'
  when 'html-49' then 'برنامج بناء المشاريع التقنية أندية طويق في الرياض وعن بعد في ١ أكتوبر ٢٠٢٦'
  when 'html-50' then 'الهاكاثون الهندسي من الهيئة السعودية للمهندسين في الرياض في ٥ أكتوبر ٢٠٢٦'
  when 'html-51' then 'رواد الألعاب من وزارة الاتصالات وتقنية المعلومات في الرياض في ١٠ أكتوبر ٢٠٢٦'
  when 'html-52' then 'جائزة نورة الملاحي من مؤسسة نورة الملاحي الأهلية عن بعد في ١٥ أكتوبر ٢٠٢٦ بجائزة ٤٠٠ ألف ريال'
  when 'html-53' then 'Operations & Execution - Consultations'
  when 'html-54' then 'تقنية المعلومات - ارشاد'
  when 'html-55' then 'Innovation - Consultations'
  when 'html-56' then 'ندعو الجميع لزيارة موقع منشآت ومتابعة حساب المستشارة هدى فلاته لكل جديد'
  else original_arabic
end,
phase = case
  when task_key in ('html-1','html-2','html-3','html-4','html-5','html-6') then 1
  when task_key in ('html-7','html-8','html-9','html-10','html-11','html-12') then 2
  when task_key in ('html-13','html-14','html-15','html-16','html-17','html-18','html-19') then 3
  when task_key in ('html-20','html-21','html-22','html-23','html-24','html-25','html-26','html-27') then 4
  when task_key in ('html-28','html-29','html-30') then 5
  when task_key in ('html-31','html-32','html-33','html-34') then 6
  when task_key in ('html-35','html-36','html-37','html-38','html-39','html-40') then 7
  when task_key in ('html-41','html-42','html-43','html-44','html-45','html-46','html-47','html-48','html-49','html-50','html-51','html-52') then 8
  when task_key in ('html-53','html-54','html-55','html-56') then 9
  else phase
end,
updated_at = now();

create index if not exists monshaat_tasks_phase_idx on public.monshaat_tasks(phase);
